using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class PGWodehouse
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Routine is the death to heroism.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It is a good rule in life never to apologize. The right sort of people do not want apologies, and the wrong sort take a mean advantage of them.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Of all sad words of tongue or pen, the saddest are these, 'It might have been.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "So was victory turned into defeat, and Billy's jaw became squarer and his eye more full of the light of battle than ever.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "The village of Market Blandings is one of those sleepy hamlets which modern progress has failed to touch... The church is Norman, and the intelligence of the majority of the natives palaeozoic.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "In English country towns, if the public houses do not actually outnumber the inhabitants, they all do an excellent trade. It is only when they are two to one that hard times hit them and set the innkeepers to blaming the government.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'As a sleuth you are poor. You couldn't detect a bass-drum in a telephone-booth.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "There are some things a chappie's mind absolutely refuses to picture, and Aunt Julia singing 'Rumpty-tiddley-umpty-ay' is one of them.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He wore the unmistakable look of a man about to be present at a row between women, and only a wet cat in a strange backyard bears itself with less jauntiness than a man faced by such a prospect.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "And she's got brains enough for two, which is the exact quantity the girl who marries you will need.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "The fascination of shooting as a sport depends almost wholly on whether you are at the right or wrong end of the gun.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "A man's subconscious self is not the ideal companion. It lurks for the greater part of his life in some dark den of its own, hidden away, and emerges only to taunt and deride and increase the misery of a miserable hour.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "At the age of eleven or thereabouts women acquire a poise and an ability to handle difficult situations which a man, if he is lucky, manages to achieve somewhere in the later seventies.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Boyhood, like measles, is one of those complaints which a man should catch young and have done with, for when it comes in middle life it is apt to be serious.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Has anybody ever seen a drama critic in the daytime? Of course not. They come out after dark, up to no good.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He trusted neither of them as far as he could spit, and he was a poor spitter, lacking both distance and control.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It was one of those cold, clammy, accusing sort of eyes--the kind that makes you reach up to see if your tie is straight: and he looked at me as I were some sort of unnecessary product which Cuthbert the Cat had brought in after a ramble among the local ash-cans.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It was a cold, disapproving gaze, such as a fastidious luncher who was not fond of caterpillars might have directed at one which he had discovered in his portion of salad...", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Dark hair fell in a sweep over his forehead. He looked like a man who would write ''vers libre'', as indeed he did.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Love has had a lot of press-agenting from the oldest times; but there are higher, nobler things than love.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He was not a man who prattled readily, especially in a foreign tongue. He gave the impression that each word was excavated from his interior by some up-to-date process of mining.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "No novelists any good except me. Sovietski--yah! Nastikoff--bah! I spit me of zem all. No novelists anywhere any good except me. P. G. Wodehouse and Tolstoi not bad. Not good, but not bad. No novelists any good except me.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "\"What I want to know is what a fellow does when he plays golf. Tell me in as few words as you can just what it's all about.\" -- \"You hit a ball with a stick until it falls into a hole.\"", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It was my Uncle George who discovered that alcohol was a food well in advance of modern medical thought.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I turned to Aunt Agatha, whose demeanour was now rather like that of one who, picking daisies on the railway, has just caught the down express in the small of the back.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Jeeves lugged my purple socks out of the drawer as if he were a vegetarian fishing a caterpillar out of his salad.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I once got engaged to his daughter Honoria, a ghastly dynamic exhibit who read Nietzsche and had a laugh like waves breaking on a stern and rockbound coast.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Anybody can talk me round. If I were in a Trappist monastery, the first thing that would happen would be that some smooth performer would lure me into some frightful idiocy against my better judgment by means of the deaf-and-dumb language.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'Alf Todd,' said Ukridge, soaring to an impressive burst of imagery, 'has about as much chance as a one-armed blind man in a dark room trying to shove a pound of melted butter into a wild-cat's ear with a red-hot needle.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Whenever I meet Ukridge's Aunt Julia I have the same curious illusion of having just committed some particularly unsavoury crime and-what is more-of having done it with swollen hands, enlarged feet, and trousers bagging at the knee on a morning when I had omitted to shave.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He resembled a minor prophet who had been hit behind the ear with a stuffed eel-skin.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He committed mayhem upon his person. He did everything to him that a man can do who is hampered with boxing gloves.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'Yes, sir,' said Jeeves in a low, cold voice, as if he had been bitten in the leg by a personal friend.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Honoria, you see, is one of those robust, dynamic girls with the muscles of a welterweight and a laugh like a squadron of cavalry charging over a tin bridge. A beastly thing to face over the breakfast table. Brainy, moreover.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "While they were content to peck cautiously at the ball, he never spared himself in his efforts to do it a violent injury.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Bradbury Fisher shuddered from head to foot, and his legs wobbled like asparagus stalks.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "At this moment, the laurel bush, which had hitherto not spoken, said \"Psst!\"", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "This done, he felt a little-not much, but a little-better. Before, he would have gladly murdered Beach and James and danced on their graves. Now, he would have been satisfied with straight murder.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "When you have just been told that the girl you love is definitely betrothed to another, you begin to understand how Anarchists must feel when the bomb goes off too soon.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "The Right Hon. was a tubby little chap who looked as if he had been poured into his clothes and had forgotten to say `When!'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "My Aunt Dahlia has a carrying voice... If all other sources of income failed, she could make a good living calling the cattle home across the Sands of Dee.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "She fitted into my biggest armchair as if it had been built round her by someone who knew they were wearing armchairs tight about the hips that season.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Unseen, in the background, Fate was quietly slipping the lead into the boxing-glove.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "In one second, without any previous training or upbringing, he had become the wettest man in Worcestershire.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'The modern young man,' said Aunt Dahlia, 'is a congenital idiot and wants a nurse to lead him by the hand and some strong attendant to kick him regularly at intervals of a quarter of an hour.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I can't stand Paris. I hate the place. Full of people talking French, which is a thing I bar. It always seems to me so affected.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He groaned slightly and winced, like Prometheus watching his vulture dropping in for lunch.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "\"Oh, yes, he thinks a lot of you. I remember his very words. 'Mr Wooster, miss,' he said, 'is, perhaps, mentally somewhat negligible but he has a heart of gold.'\"", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "You know how it is with some girls. They seem to take the stuffing right out of you. I mean to say, there is something about their personality that paralyses the vocal cords and reduces the contents of the brain to cauliflower.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Scarcely had I entered the sitting-room when I found ... what appeared at first sight to be the Devil, A closer scrutiny informed me that it was Gussie Fink-Nottle, dressed as Mephistopheles.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "We do not tell old friends beneath our roof-tree that they are an offence to the eyesight.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Gussie, a glutton for punishment, stared at himself in the mirror.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "The female in question was a sloppy pest", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "There is enough sadness in life without having fellows like Gussie Fink-Nottle going about in sea boots.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "A slight throbbing about the temples told me that this discussion had reached saturation point.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I consider that of all the dashed silly, drivelling ideas I ever heard in my puff this is the most blithering and futile. It won't work. Not a chance.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "And a moment later there was a sound like a mighty rushing wind, and the relative had crossed the threshold at fifty m.p.h. under her own steam.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "My Aunt Agatha, the curse of the Home Counties and a menace to one and all.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "She cried in a voice that hit me between the eyebrows and went out at the back of my head.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I goggled. Her words did not appear to make sense. They seemed the mere aimless vapouring of an aunt who has been sitting out in the sun without a hat.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He had been looking like a dead fish. He now looked like a deader fish, one of last year's, cast up on some lonely beach and left there at the mercy of the wind and tides.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "And, anyway, no matter how much you may behave like the deaf adder of Scripture which, as you are doubtless aware, the more one piped, the less it danced, or words to that effect, I shall carry on as planned.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "In build and appearance, Tuppy somewhat resembles a bulldog, and his aspect now was that of one of these fine animals who has just been refused a slice of cake.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "And as for Gussie Fink-Nottle, many an experienced undertaker would have been deceived by his appearance and started embalming him on sight.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He uttered a coarse expression which I wouldn't have thought he would have known. It just shows that you can bury yourself in the country and still somehow acquire a vocabulary. No doubt one picks up things from the neighbours - the vicar, the local doctor, the man who brings the milk, and so on.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Though never for an instant faltering in my opinion that Augustus Fink-Nottle was Nature's final word in cloth-headed guffins, I liked the man, wished him well.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Then he rose and began to pace the room in an overwrought sort of way, like a zoo lion who has heard the dinner-gong go and is hoping the keeper won't forget him in the general distribution.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I wouldn't have said off-hand that I had a subconscious mind, but I suppose I must without knowing it, and no doubt it was there, sweating away diligently at the old stand, all the while the corporeal Wooster was getting his eight hours.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "If you can visualize a bulldog which has just been kicked in the ribs and had its dinner sneaked by the cat, you will have Hildebrand Glossop as he now stood before me.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "\"My dear Tuppy, does one bandy a woman's name?\" -- \"One does if one doesn't want one's ruddy head pulled off.\"", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "The fellow with a face rather like a walnut.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Nature, when planning this sterling fellow, shoved in a lot more lower jaw than was absolutely necessary and made the eyes a bit too keen and piercing for one who was neither an Empire builder nor a traffic policeman.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "\"She loves this newt-nuzzling blister.\"", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It isn't often that Aunt Dahlia, lets her angry passions rise, but when she does, strong men climb trees and pull them up after them.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Even at normal times Aunt Dahlia's map tended a little towards the crushed strawberry. But never had I seen it take on so pronounced a richness as now. She looked like a tomato struggling for self-expression.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "If the prophet Job were to walk into the room at this moment, I could sit swapping hard-luck stories with him till bedtime.\"", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I charged into something which might have been a tree, but was not - being, in point of fact, Jeeves.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It is never difficult to distinguish between a Scotsman with a grievance and a ray of sunshine.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "A sort of gulpy, gurgly, plobby, squishy, wofflesome sound, like a thousand eager men drinking soup in a foreign restaurant.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He had never acted in his life, and couldn't play the pin in ''Pinafore''.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "A young man with dark circles under his eyes was propping himself up against a penny-in-the-slot machine. An undertaker, passing at that moment, would have looked at this young man sharply, scenting business. So would a buzzard.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'Didn't Frankenstein get married?' 'Did he?' said Eggy. 'I don't know. I never met him. Harrow man, I expect.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "If Eggy wanted to get spliced, let him, was the way I looked at it. Marriage might improve him. It was difficult to think of anything that wouldn't.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I shuddered from stem to stern, as stout barks do when buffeted by the waves.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It was a harsh, rasping voice, in its timbre not unlike a sawmill.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'Do you know,' said a thoughtful Bean, 'I'll bet that if all the girls Freddie Widgeon has loved were placed end to end-not that I suppose one could do it-they would reach half-way down Piccadilly.' 'Further than that,' said the Egg. 'Some of them were pretty tall.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'You must remember, Father,' said Mavis, in a voice which would have had an Eskimo slapping his ribs and calling for the steam-heat, 'that this girl was probably very pretty. So many of these New York girls are. That would, of course, explain Frederick's behaviour.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I could see that, if not actually disgruntled, he was far from being gruntled.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Aunt Agatha, who eats broken bottles and wears barbed wire next to the skin.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It is no use telling me there are bad aunts and good aunts. At the core, they are all alike. Sooner or later, out pops the cloven hoof.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'Have you ever seen Spode eat asparagus?' 'No.' 'Revolting. It alters one's whole conception of Man as Nature's last word.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Prismatic is the only word for those frightful tweeds and, oddly enough, the spectacle of them had the effect of steadying my nerves. They gave me the feeling that nothing mattered.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'There are moments, Jeeves, when one asks oneself, \"Do trousers matter?\"' 'The mood will pass, sir.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Stiffy was one of those girls who enjoy in equal quantities the gall of an army mule and the calm insouciance of a fish on a slab of ice.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "There came from without the hoof-beats of a galloping relative and Aunt Dahlia whizzed in.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "'You can't be a successful Dictator and design women's underclothing.' 'No, sir.' 'One or the other. Not both.' 'Precisely, sir.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "...his head emerged cautiously, like that of a snail taking a look around after a thunderstorm.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I don't suppose she would recognize a deep, beautiful thought if you handed it to her on a skewer with tartare sauce.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "She snorted with a sudden violence which twenty-four hours earlier would have unmanned me completely. Even in my present tolerably robust condition, it affected me like one of those gas explosions which slay six.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Like so many substantial citizens of America, he had married young and kept on marrying, springing from blonde to blonde like the chamois of the Alps leaping from crag to crag.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Directing an austere look at Tubby's receding back, she spoke in a cold crisp voice which sounded in the drowsy stillness like ice tinkling in a pitcher.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Whatever may be said in favour of the Victorians, it is pretty generally admitted that few of them were to be trusted within reach of a trowel and a pile of bricks.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It began to be borne in upon Lord Ickenham that in planning to appeal to the Duke's better feelings he had omitted to take into his calculations the fact that he might not have any.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "The cosy glow which had been enveloping the Duke became shot through by a sudden chill. It was as if he had been luxuriating in a warm shower-bath, and some hidden hand had turned on the cold tap.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "The Duke's moustache was rising and falling like seaweed on an ebb-tide.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He felt like a man who, chasing rainbows, has had one of them suddenly turn and bite him in the leg.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Bingo swayed like a jelly in a high wind.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "His whole aspect was that of a man who has unexpectedly been struck by lightning.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Mere abuse is no criticism.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Aunt Agatha is like an elephant-not so much to look at, for in appearance she resembles more a well-bred vulture, but because she never forgets.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "His eyes were rolling in their sockets, and his face had taken on the colour and expression of a devout tomato. I could see he loved like a thousand bricks.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I suppose this was really the moment for embarking upon an impassioned defence of Boko, stressing his admirable qualities. Not being able to think of any, however, I remained silent.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "On his good mornings, I don't suppose there are more than a handful of men in the W. 1 postal district of London swifter to spot oompus-boompus than Bertram Wooster, and this was one of my particularly good mornings. I saw the whole hideous plot.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I don't say I've got much of a soul, but, such as it is, I'm perfectly satisfied with the little chap. I don't want people fooling about with it. 'Leave it alone,' I say. 'Don't touch it. I like it the way it is.'", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He vanished abruptly, like an eel going into mud.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "However devoutly a girl may worship the man of her choice, there always comes a time when she feels an irresistible urge to haul off and let him have it in the neck.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "She laughed - a solo effort. Nothing in the prevailing circumstances made me feel like turning it into a duet.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "There was a sound in the background like a distant sheep coughing gently on a mountainside. Jeeves sailing into action.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "We exchanged a meaning glance. Or, rather, two meaning glances, I giving him one and he giving me the other.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Breakfast had been prepared by the kitchen maid, an indifferent performer who had used the scorched earth policy on the bacon again.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "The stationmaster's whiskers are of a Victorian bushiness and give the impression of having been grown under glass.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "As far as the eye could reach, I found myself gazing on a surging sea of aunts. There were tall aunts, short aunts, stout aunts, thin aunts, and an aunt who was carrying on a conversation in a low voice to which nobody seemed to be paying the slightest attention.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "For an author Jerry Vail was rather nice-looking, most authors, as is widely known, resembling in appearance the more degraded types of fish, unless they look like birds, when they could pass as vultures and no questions asked.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Ice formed on the butler's upper slopes.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It was a confusion of ideas between him and one of the lions he was hunting in Kenya that had caused A. B. Spottsworth to make the obituary column. He thought the lion was dead, and the lion thought it wasn't.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I agreed the situation was sticky. Indeed, offhand it was difficult to see how it could have been more glutinous.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "As plainly as if it had been the top line on the oculist's chart I could see what the future held for Bertram.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Before my eyes he wilted like a wet sock.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "And as he, too, seemed disinclined for chit-chat, we stood for some moments like a couple of Trappist monks who have run into each other at the dog races.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Oh, Bertie, if I ever called you a brainless poop who ought to be given a scholarship at some lunatic asylum, I take back the words.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "I don't know if you have ever seen a tiger of the jungle drawing a deep breath preparatory to doing a swan dive and landing with both the feet on the backbone of one of the minor fauna. Probably not, nor, as a matter of fact, have I.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "He had that self-reproachful feeling of having been remiss which comes to Generals who wake up one morning to discover that they have carelessly allowed themselves to be outflanked.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Never put anything on paper, my boy, and never trust a man with a small black moustache.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "It has been well said that an author who expects results from a first novel is in a position similar to that of a man who drops a rose petal down the Grand Canyon of Arizona and listens for the echo.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Attila the Hun might have broken off his engagement to her, but nobody except Attila the Hun, and he only on one of his best mornings.", Author = "P. G. Wodehouse" },
            new Quote { Id = "https://en.wikiquote.org/wiki/P._G._Wodehouse", Text = "Whenever there is a job to be taken on of a kind calculated to make Humanity shudder, the cry goes up, 'Let Wooster do it.'", Author = "P. G. Wodehouse" },
        };
    }
}